'use client';

import classNames from 'classnames';
import {
  memo, useCallback, useEffect, useId, useMemo, useRef, useState,
} from 'react';
import { useTextField } from 'react-aria';
import { toast } from 'react-toastify';
import { createEditor, Editor, Transforms } from 'slate';
import { withHistory } from 'slate-history';
import {
  Editable, ReactEditor, Slate, withReact,
} from 'slate-react';

import {
  decorator, flattenNodeText, getInitialValue, onChange as onChangeHandler,
  onCopy, onKeyDown, renderElementFactory, RenderLeaf, withEmojis, withNormalizeNode,
} from './utils';

import type {
  ClipboardEventHandler, FC, TouchEvent, TouchEventHandler,
} from 'react';
import type { AriaTextFieldProps } from 'react-aria';
import type { InteractiveParser } from 'simple-markdown';
import type { Descendant } from 'slate';
import type { EditableProps } from 'slate-react/dist/components/editable';

import { useEmojiPickerState } from '~/components/EmojiPicker/utils';
import Invisible from '~/components/Invisible';
import { useMarkdown } from '~/providers/MarkdownProvider';
import { omit, shallowEqual } from '~/utils';
import { useMounted } from '~/utils/hooks';

const MAX_PASTE_LENGTH = 6000;

type FixedEditableProps = Omit<EditableProps, keyof AriaTextFieldProps>;

interface Props extends AriaTextFieldProps, FixedEditableProps {
  initialValue: string;
  isEmbed?: boolean;
  onChange: (value: string) => void;
  emojiParser: InteractiveParser;
  contentParser: InteractiveParser;
  partialMarkdown?: boolean;
}

const SlateEditor: FC<Props> = (props) => {
  const {
    initialValue, className, onChange, emojiParser, contentParser, onKeyDown: propsOnKeyDown,
    isEmbed = false, partialMarkdown = false,
  } = props;

  const [descendants, setDescendants] = useState<Descendant[]>(() => getInitialValue(initialValue, emojiParser, partialMarkdown));

  // fetch dynamic markdown if not already
  useMarkdown();

  const string = flattenNodeText(descendants);
  useEffect(() => { onChange(string); }, [string]);

  const editor = useMemo(() => withNormalizeNode(withEmojis(withHistory(withReact(createEditor()))), partialMarkdown, emojiParser), []);
  const { inputProps } = useTextField({ ...props, type: 'div', autoCapitalize: undefined }, useRef(null));
  const focusRef = useRef<HTMLDivElement>(null);

  const handleFocus = useCallback((e?: TouchEvent<HTMLDivElement>) => {
    focusRef.current?.focus();

    setTimeout(() => {
      try {
        const editorEl = ReactEditor.toDOMNode(editor, editor);
        if (!editor.selection) {
          Transforms.select(editor, Editor.end(editor, []));
          ReactEditor.focus(editor);
        } else {
          const domRange = ReactEditor.toDOMRange(editor, editor.selection);
          const domSelection = window.getSelection();
          domSelection?.removeAllRanges();
          domSelection?.addRange(domRange);
          editorEl.focus();
        }
      } catch {
        // DOM node not yet mapped — editor may still be mounting
      }
    }, 300);
  }, []);

  const id = useId();
  const mounted = useMounted();
  useEffect(() => { if (mounted) handleFocus(); }, [mounted]);

  useEffect(() => { if (!partialMarkdown) editor.children = descendants; }, [string.split('`').length]);

  const { setOnInsert, showPicker, setShowPicker } = useEmojiPickerState();
  useEffect(() => {
    setOnInsert((emoji) => {
      editor.insertText(emoji);
      handleFocus();
    });
  }, [setOnInsert]);

  const moveRef = useRef(false);

  return (
    <>
      <Invisible
        ref={focusRef}
        className='fixed top-0 left-0 min-h-[0.25rem] min-w-[0.25rem] translate-y-[9999px] !text-base opacity-5'
        contentEditable
      />
      <Slate
        editor={editor}
        initialValue={useMemo(() => descendants, [])} // initial value, managed internally from here on
        onValueChange={useCallback(onChangeHandler(editor, setDescendants), [])}
      >
        <Editable
          {...inputProps}
          id={id}
          inputMode={showPicker ? 'none' : 'text'}
          aria-describedby={id}
          className={classNames(className)}
          renderElement={useCallback(renderElementFactory(isEmbed), [])}
          renderLeaf={useCallback(RenderLeaf, [])}
          decorate={useCallback(decorator(editor, useMounted(), isEmbed, contentParser), [])}
          onCopy={useCallback(onCopy(editor), [])}
          onCut={useCallback(onCopy(editor, true), [])}
          onPaste={useCallback<ClipboardEventHandler<HTMLDivElement>>((e) => {
            const pastedText = e.clipboardData.getData('text/plain');
            if (partialMarkdown && pastedText.includes('\n')) {
              toast.error('This field does not support multiple lines.');
              e.preventDefault();
            } else if (pastedText.length > MAX_PASTE_LENGTH) {
              toast.error('Text too long.');
              e.preventDefault();
            }
          }, [])}
          onKeyDown={useCallback(onKeyDown(editor, partialMarkdown, propsOnKeyDown), [])}
          onTouchStart={useCallback(() => { moveRef.current = false; }, [])}
          onTouchMove={useCallback(() => { moveRef.current = true; }, [])}
          onTouchEnd={useCallback<TouchEventHandler<HTMLDivElement>>((e) => {
            if (!moveRef.current) {
              setShowPicker(false);
              handleFocus(e);
            }
          }, [])}
        />
      </Slate>
    </>
  );
};

export default memo(SlateEditor, (prevProps, nextProps) => shallowEqual(omit(prevProps, ['initialValue']), omit(nextProps, ['initialValue'])));
